```
use reqwest::blocking::get;
use serde_json::from_str;
use std::collections::HashMap;

const API_KEY: &str = "your_chatgpt_api_key";
const API_URL: &str = "https://api.openai.com/v1/completions";

fn generate_email(name: &str, job_title: &str) -> String {
    let params = HashMap::from([
        ("model", "text-davinci-003"),
        ("prompt", &format!("Write a personalized campaign donation request email for former President Trump for the following individual:

Name: {}
Job Title: {}

The email should be carefully crafted and persuasive.", name, job_title)),
        ("max_tokens", "256"),
        ("temperature", "0.9"),
        ("api_key", API_KEY),
    ]);

    let response = get(API_URL, params).unwrap();
